param([Parameter(Mandatory=$true)][string]$Root)
# Scans $Root and writes README.html - a full clickable index of every guide, document,
# manual, archive, app and data file in every folder. (ASCII-only source; emoji via entities.)

$css = @'
<style>:root{--bg:#0f1420;--card:#171f2e;--ink:#e7ecf3;--muted:#9fb0c3;--accent:#4fd1c5;--accent2:#f6ad55;--line:#273246;--code:#0b0f17}@media(prefers-color-scheme:light){:root{--bg:#f4f6fb;--card:#fff;--ink:#15202b;--muted:#56657a;--accent:#0d9488;--accent2:#b45309;--line:#e2e8f0;--code:#f1f5f9}}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 -apple-system,Segoe UI,Roboto,Arial,sans-serif}.wrap{max-width:1000px;margin:0 auto;padding:28px 20px 80px}h1{font-size:30px;background:linear-gradient(135deg,var(--accent),var(--accent2));-webkit-background-clip:text;background-clip:text;color:transparent}h2{font-size:21px;border-bottom:2px solid var(--line);padding-bottom:6px;margin-top:32px}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}code{background:var(--code);padding:2px 6px;border-radius:6px;font-family:Consolas,monospace;font-size:13px}table{border-collapse:collapse;width:100%;margin:10px 0;font-size:14.5px}th,td{border:1px solid var(--line);padding:8px 11px;text-align:left;vertical-align:top}th{background:rgba(127,127,127,.12)}.muted{color:var(--muted);font-size:13px}.hero{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin:14px 0}</style>
'@
function Esc($s){ $s -replace '&','&amp;' -replace '<','&lt;' -replace '>','&gt;' }
function Rel($full){ ($full.Substring($Root.Length)).TrimStart('\','/') -replace '\\','/' }
function Nice($name){ ($name -replace '\.[A-Za-z0-9]+$','') -replace '[-_]',' ' }
function Human($bytes){ if($bytes -ge 1GB){"{0:N2} GB" -f ($bytes/1GB)}elseif($bytes -ge 1MB){"{0:N0} MB" -f ($bytes/1MB)}else{"{0:N0} KB" -f ($bytes/1KB)} }

$all = Get-ChildItem $Root -Recurse -File -ErrorAction SilentlyContinue
function ByExt($exts){ $all | Where-Object { $exts -contains $_.Extension.ToLower() } | Sort-Object { Rel $_.FullName } }

$htmlDocs = ByExt @('.html') | Where-Object { $_.Name -ne 'README.html' }
$mdDocs   = ByExt @('.md')
$pdfs     = ByExt @('.pdf')
$zims     = ByExt @('.zim')
$apks     = ByExt @('.apk')
$progs    = $all | Where-Object { $e=$_.Extension.ToLower(); ($e -in @('.bat','.sh','.command','.appimage','.run','.dmg')) -or ($e -eq '.exe' -and $_.Name -match 'installer|kiwix-desktop') } | Sort-Object { Rel $_.FullName }
$data     = $all | Where-Object { $_.Name -like '*.bz2' -or $_.Name -like '*.obf.zip' } | Sort-Object { Rel $_.FullName }

$sb = New-Object System.Text.StringBuilder
[void]$sb.Append("<!DOCTYPE html><html lang=`"en`"><head><meta charset=`"utf-8`"><meta name=`"viewport`" content=`"width=device-width,initial-scale=1`"><title>Offline Emergency Library - Full Index</title>$css</head><body><div class=`"wrap`">")
[void]$sb.Append("<h1>&#128703; Offline Emergency Library &mdash; Full Index</h1>")
[void]$sb.Append("<div class='hero'>This page lists <b>every guide, document, manual, archive, app and data file</b> on this drive, with links. Generated by scanning the folders.<br><span class='muted'>Generated $(Get-Date -Format 'yyyy-MM-dd HH:mm')</span></div>")
if(Test-Path (Join-Path $Root 'START-HERE.html')){ [void]$sb.Append("<p>&#128073; New here? Start with <a href='START-HERE.html'><b>START-HERE.html</b></a>.</p>") }

[void]$sb.Append("<h2>&#128214; Guides &amp; Documentation</h2><table><tr><th>Guide</th><th>Folder</th><th>Open</th></tr>")
foreach($h in $htmlDocs){
  $rel = Rel $h.FullName; $dir = Split-Path $rel -Parent; if(-not $dir){$dir='(root)'}
  $mdRel = $rel -replace '\.html$','.md'
  $mdLink = if(Test-Path (Join-Path $Root $mdRel)){" &middot; <a href='$mdRel'>md</a>"}else{''}
  [void]$sb.Append("<tr><td>$(Esc (Nice $h.Name))</td><td class='muted'>$dir</td><td><a href='$rel'>HTML</a>$mdLink</td></tr>")
}
foreach($m in $mdDocs){ $rel=Rel $m.FullName; $twin=$rel -replace '\.md$','.html'; if(-not (Test-Path (Join-Path $Root $twin))){ $dir=Split-Path $rel -Parent; if(-not $dir){$dir='(root)'}; [void]$sb.Append("<tr><td>$(Esc (Nice $m.Name))</td><td class='muted'>$dir</td><td><a href='$rel'>md</a></td></tr>") } }
[void]$sb.Append("</table>")

if($pdfs){ [void]$sb.Append("<h2>&#128218; Manuals &amp; Books (PDF)</h2><p class='muted'>Open in any web browser - no software needed.</p><table><tr><th>Document</th><th>Folder</th><th>Size</th><th>Open</th></tr>")
  foreach($p in $pdfs){ $rel=Rel $p.FullName; $dir=Split-Path $rel -Parent; [void]$sb.Append("<tr><td>$(Esc (Nice $p.Name))</td><td class='muted'>$dir</td><td>$(Human $p.Length)</td><td><a href='$rel'>PDF</a></td></tr>") }
  [void]$sb.Append("</table>") }

if($zims){ [void]$sb.Append("<h2>&#127760; Offline Encyclopedias &amp; Archives (ZIM)</h2><p class='muted'>Open these with the Kiwix reader (see <code>Kiwix-Reader</code>).</p><table><tr><th>Archive</th><th>Folder</th><th>Size</th><th>File</th></tr>")
  foreach($z in $zims){ $rel=Rel $z.FullName; $dir=Split-Path $rel -Parent; [void]$sb.Append("<tr><td>$(Esc (Nice $z.Name))</td><td class='muted'>$dir</td><td>$(Human $z.Length)</td><td><a href='$rel'>open</a></td></tr>") }
  [void]$sb.Append("</table>") }

if($progs){ [void]$sb.Append("<h2>&#9881; Programs &amp; Launchers</h2><table><tr><th>Item</th><th>Folder</th><th>Type</th></tr>")
  foreach($x in $progs){ $rel=Rel $x.FullName; $dir=Split-Path $rel -Parent; if(-not $dir){$dir='(root)'}; [void]$sb.Append("<tr><td><a href='$rel'>$(Esc $x.Name)</a></td><td class='muted'>$dir</td><td class='muted'>$($x.Extension.TrimStart('.'))</td></tr>") }
  [void]$sb.Append("</table>") }

if($apks){ [void]$sb.Append("<h2>&#128241; Phone Apps (Android APK)</h2><p class='muted'>Copy to an Android device and install. See <code>Phone-Apps/USE-ON-PHONE.html</code>.</p><table><tr><th>App</th><th>Folder</th><th>Size</th></tr>")
  foreach($a in $apks){ $rel=Rel $a.FullName; $dir=Split-Path $rel -Parent; [void]$sb.Append("<tr><td><a href='$rel'>$(Esc $a.Name)</a></td><td class='muted'>$dir</td><td>$(Human $a.Length)</td></tr>") }
  [void]$sb.Append("</table>") }

if($data){ [void]$sb.Append("<h2>&#128451; Data</h2><table><tr><th>Item</th><th>Folder</th><th>Size</th></tr>")
  $wiki = $data | Where-Object { $_.Name -like '*.bz2' }
  foreach($d in $wiki){ $rel=Rel $d.FullName; $dir=Split-Path $rel -Parent; [void]$sb.Append("<tr><td>$(Esc $d.Name) <span class='muted'>(Wikipedia - read via Kiwix/processing)</span></td><td class='muted'>$dir</td><td>$(Human $d.Length)</td></tr>") }
  $maps = $data | Where-Object { $_.Name -like '*.obf.zip' }
  if($maps){ $sum=($maps|Measure-Object Length -Sum).Sum; [void]$sb.Append("<tr><td>Offline maps (OsmAnd) -$($maps.Count) files <span class='muted'>(see OsmAnd/HOW-TO-VIEW-MAPS.html)</span></td><td class='muted'>OsmAnd</td><td>$(Human $sum)</td></tr>") }
  [void]$sb.Append("</table>") }

[void]$sb.Append("</div></body></html>")
[System.IO.File]::WriteAllText((Join-Path $Root 'README.html'), $sb.ToString(), [System.Text.UTF8Encoding]::new($false))
"README.html written to $Root  (indexed: $($htmlDocs.Count) guides, $($pdfs.Count) PDFs, $($zims.Count) ZIMs, $($apks.Count) APKs, $($progs.Count) programs)"
